// Lunes a domingo de la semana que acaba de terminar.
const hoy = new Date();
const diaSemana = (hoy.getUTCDay() + 6) % 7;        // 0 = lunes
const lunesEsta = new Date(Date.UTC(
  hoy.getUTCFullYear(), hoy.getUTCMonth(), hoy.getUTCDate() - diaSemana));

const desde = new Date(lunesEsta.getTime() - 7 * 86400000);
const hasta = new Date(lunesEsta.getTime() - 1 * 86400000);

const iso = (d) => d.toISOString().slice(0, 10);

return [{ json: { desde: iso(desde), hasta: iso(hasta) } }];

// El correo lleva el texto redactado Y las cifras crudas.
// Asi cualquiera puede comprobar si la redaccion corresponde a los datos.
const ia = $input.first().json.output ?? $input.first().json;
const datos = $('Agregar resultados').first().json;

const linea = (k, v) => `${k}: ${v}`;

const cuerpo = [
  ia.titulo ?? 'Resumen de movimientos',
  '',
  ia.resumen ?? '',
  '',
  ...(ia.puntos ?? []).map((p) => `- ${p}`),
  '',
  '--- Cifras del periodo (calculadas por el flujo, no por el modelo) ---',
  linea('Periodo', `${datos.desde} a ${datos.hasta}`),
  linea('Movimientos', datos.total_movimientos),
  linea('Unidades', datos.unidades_totales),
  linea('Productos distintos', datos.productos_distintos),
  linea('Con alerta de stock', datos.movimientos_con_alerta),
  '',
  'Productos con mas salida:',
  ...(datos.top_productos ?? []).map((p) => `  ${p.sku}: ${p.unidades} unidades`),
  '',
  'Movimientos por motivo:',
  ...Object.entries(datos.por_motivo ?? {}).map(([m, n]) => `  ${m}: ${n}`),
  '',
  `Origen: ${datos.origen}`,
].join('\n');

return [{ json: {
  asunto: ia.titulo ?? `Resumen de movimientos ${datos.desde} a ${datos.hasta}`,
  cuerpo,
  requiere_atencion: ia.requiere_atencion === true,
} }];

// La cadena o el parser no entregaron algo utilizable.
// El informe sale igual, con las cifras, diciendo que no hubo redaccion.
const datos = $('Agregar resultados').first().json;
const error = $input.first().json.error?.message ?? 'La cadena no devolvio un resultado valido.';

const cuerpo = [
  'No se pudo generar el texto del resumen. Las cifras del periodo si se consultaron.',
  '',
  `Motivo tecnico: ${error}`,
  '',
  '--- Cifras del periodo ---',
  `Periodo: ${datos.desde} a ${datos.hasta}`,
  `Movimientos: ${datos.total_movimientos}`,
  `Unidades: ${datos.unidades_totales}`,
  `Con alerta de stock: ${datos.movimientos_con_alerta}`,
  '',
  `Origen: ${datos.origen}`,
].join('\n');

return [{ json: {
  asunto: `[sin redaccion] Resumen ${datos.desde} a ${datos.hasta}`,
  cuerpo,
  requiere_atencion: true,
} }];

// Puede ser que no hubo movimientos, o que no se pudo consultar.
// Son cosas distintas y el correo debe decir cual.
const d = $input.first().json;

const explicacion = d.estado === 'sin_movimientos'
  ? 'No se registraron movimientos en el periodo. La consulta funciono correctamente.'
  : `No se pudo consultar el periodo (estado: ${d.estado}). ${d.motivo ?? ''}`;

return [{ json: {
  asunto: `Resumen ${d.desde} a ${d.hasta} - sin cifras`,
  cuerpo: [explicacion, '', 'No se llamo al modelo porque no hay datos que redactar.'].join('\n'),
  requiere_atencion: d.estado !== 'sin_movimientos',
} }];

// S-06. Ningun numero del texto redactado deberia ser ajeno a las cifras calculadas.
const cifras = $('Agregar resultados').first().json;
const salida = { ...$input.first().json };

const texto = [salida.titulo, salida.resumen, ...(salida.puntos ?? [])].join(' ');
const enTexto = (texto.match(/\d+/g) ?? []).map(Number);

const admitidos = new Set([
  cifras.total_movimientos, cifras.unidades_totales,
  cifras.productos_distintos, cifras.movimientos_con_alerta,
  ...(cifras.top_productos ?? []).map(p => p.unidades),
  ...Object.values(cifras.por_motivo ?? {}),
]);
// Las fechas del periodo tambien aparecen como numeros en el texto.
for (const f of [cifras.desde, cifras.hasta]) {
  for (const parte of String(f).split('-')) { admitidos.add(Number(parte)); }
}

const ajenos = enTexto.filter(n => !admitidos.has(n));
if (ajenos.length > 0) {
  salida.resumen = `[REVISAR] El texto contiene cifras que no provienen del calculo: ${ajenos.join(', ')}.\n\n` + salida.resumen;
}
salida.cifras_ajenas = ajenos;
salida.requiere_revision = ajenos.length > 0;
return [{ json: salida }];

// Acepta dos formas de entrada:
//   - {desde, hasta}  cuando la llama la rama programada
//   - {query: "..."}  cuando la llama el agente, que entrega texto libre
// El agente no puede recibir campos mapeados porque la herramienta lleva el
// subworkflow embebido, y n8n no evalua los parametros ocultos de ese modo.
const entrada = $input.first().json;
const formato = /^\d{4}-\d{2}-\d{2}$/;

function rechazar(motivo) {
  return [{ json: { valido: false, estado: 'entrada_no_valida', motivo } }];
}

let desde = String(entrada.desde ?? '').trim();
let hasta = String(entrada.hasta ?? '').trim();

if (!desde || !hasta) {
  const texto = typeof entrada.query === 'string'
    ? entrada.query
    : JSON.stringify(entrada ?? {});
  const fechas = texto.match(/\d{4}-\d{2}-\d{2}/g) ?? [];
  if (fechas.length >= 2) {
    desde = fechas[0];
    hasta = fechas[1];
  } else if (fechas.length === 1) {
    desde = fechas[0];
    hasta = fechas[0];
  }
}

if (!formato.test(desde) || !formato.test(hasta)) {
  return rechazar('Entrega el periodo como "YYYY-MM-DD a YYYY-MM-DD". Recibido: ' +
                  `desde="${desde}", hasta="${hasta}".`);
}

const d = new Date(`${desde}T00:00:00Z`);
const h = new Date(`${hasta}T23:59:59Z`);

if (Number.isNaN(d.getTime()) || Number.isNaN(h.getTime())) {
  return rechazar('Alguna de las fechas no existe en el calendario.');
}
if (d > h) {
  return rechazar('El rango esta invertido: "desde" es posterior a "hasta".');
}
if ((h - d) / 86400000 > 400) {
  return rechazar('El periodo supera los 400 dias. Pide un rango mas corto.');
}

return [{ json: {
  valido: true,
  desde, hasta,
  desdeISO: d.toISOString(),
  hastaISO: h.toISOString(),
} }];

// Calcula los totales del periodo.
// El modelo NO hace esta cuenta: recibe el resultado hecho y solo lo redacta.
const respuesta = $input.first().json;
const periodo = $('Validar periodo').first().json;

const base = { desde: periodo.desde, hasta: periodo.hasta };

// Fallo tecnico: la consulta no se pudo completar.
if (respuesta.statusCode >= 300) {
  return [{ json: {
    ...base,
    estado: 'no_disponible',
    motivo: `Supabase respondio ${respuesta.statusCode}.`,
    detalle: respuesta.body?.message ?? '',
  } }];
}

const filas = Array.isArray(respuesta.body) ? respuesta.body : [];

// Respuesta de negocio: se consulto bien y no hay nada.
// No es un fallo, y no equivale a cero por error.
if (filas.length === 0) {
  return [{ json: {
    ...base,
    estado: 'sin_movimientos',
    total_movimientos: 0,
    origen: 'tabla Movimientos (datos de prueba)',
  } }];
}

let unidades = 0;
let conAlerta = 0;
const porProducto = {};
const porMotivo = {};
const porBodega = {};

for (const f of filas) {
  const cantidad = Number(f.cantidad) || 0;
  unidades += cantidad;
  if (f.alerta_enviada) conAlerta += 1;

  porProducto[f.sku] = (porProducto[f.sku] ?? 0) + cantidad;

  const motivo = f.motivo || 'sin motivo';
  porMotivo[motivo] = (porMotivo[motivo] ?? 0) + 1;

  if (f.bodega) {
    porBodega[f.bodega] = (porBodega[f.bodega] ?? 0) + cantidad;
  }
}

const top = Object.entries(porProducto)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([sku, u]) => ({ sku, unidades: u }));

return [{ json: {
  ...base,
  estado: 'consultado',
  origen: 'tabla Movimientos (datos de prueba)',
  total_movimientos: filas.length,
  unidades_totales: unidades,
  productos_distintos: Object.keys(porProducto).length,
  movimientos_con_alerta: conAlerta,
  top_productos: top,
  por_motivo: porMotivo,
  por_bodega: porBodega,
} }];

const entrada = $input.first().json;
if (typeof entrada.chatInput !== 'string' || !entrada.chatInput.trim() ||
    entrada.chatInput.length > 1200) {
  throw new Error('ENTRADA_NO_VALIDA: envia una pregunta de 1 a 1200 caracteres.');
}
if (typeof entrada.sessionId !== 'string' || !entrada.sessionId.trim() ||
    entrada.sessionId.length > 300) {
  throw new Error('SESION_NO_VALIDA: inicia la conversacion desde Open chat.');
}
return [{ json: { chatInput: entrada.chatInput.trim(), sessionId: entrada.sessionId } }];

