const recibido = $input.first().json;
const texto = typeof recibido.output === 'string' ? recibido.output.trim() : '';
return [{ json: {
  output: texto || 'No se obtuvo una respuesta utilizable. Revisa la ejecucion.',
} }];

const error = $input.first().json.error?.message ?? 'fallo no identificado';
return [{ json: {
  output: 'No pude completar la consulta por un fallo tecnico. ' +
          'No significa que no haya movimientos. Detalle: ' + error,
} }];
